const item = $input.first().json.body || $input.first().json;

const identifier = item.identifier || 'unknown@resident.com';
const failedAttemptsCount = item.failedAttemptsCount || 1;
const ipAddress = item.ipAddress || '127.0.0.1';
const userAgent = item.userAgent || 'Unknown Browser';
const recentLocations = item.recentLocations || [];
const isKnownDevice = item.isKnownDevice ?? false;

const prompt = `You are the Chief Cyber-Security Officer & Resident Identity Protector for the Mana Community App.
Analyze the following authentication attempt for brute force, credential stuffing, impossible travel, or account takeover.

Login Telemetry:
- Target Account: ${identifier}
- Consecutive Failed Attempts: ${failedAttemptsCount}
- Source IP: ${ipAddress}
- User Agent / Device: ${userAgent}
- Device Known / Recognized: ${isKnownDevice ? 'YES' : 'NO'}
- Recent Locations History: ${JSON.stringify(recentLocations)}

Security Rules:
1. 3+ failed attempts in 5 minutes: Apply temporary 5-minute cooldown.
2. 5+ failed attempts or unknown device spike: Require MFA challenge and flag account.
3. 10+ failed attempts from anomalous IP: Apply immediate 30-minute lockout and notify resident.
4. Avoid locking out legitimate residents who made a simple typo.

Respond ONLY with a valid JSON object matching this schema:
{
  "riskLevel": "LOW" | "MEDIUM" | "HIGH" | "CRITICAL",
  "riskScore": number (0 to 100),
  "recommendedAction": "ALLOW" | "REQUIRE_MFA_CHALLENGE" | "TEMPORARY_COOLDOWN" | "ACCOUNT_LOCKOUT",
  "cooldownMinutes": number,
  "isAttackPattern": boolean,
  "securityNotificationMessage": "Clear, calm SMS/WhatsApp security alert to the resident explaining the login protection status",
  "securityAdminBrief": "Technical summary for the society cyber-security log"
}`;

return [{
  json: {
    identifier,
    failedAttemptsCount,
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsedRuling = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsedRuling = JSON.parse(rawText);
} catch (err) {
  parsedRuling = {
    riskLevel: "MEDIUM",
    riskScore: 40,
    recommendedAction: "TEMPORARY_COOLDOWN",
    cooldownMinutes: 5,
    isAttackPattern: false,
    securityNotificationMessage: "Multiple unsuccessful login attempts detected. For your security, please wait 5 minutes before trying again.",
    securityAdminBrief: "Fallback protection triggered: cooldown enforced."
  };
}

const meta = $('Prepare Security Audit Prompt').first().json;

return [{
  json: {
    status: "success",
    identifier: meta.identifier,
    evaluatedAt: new Date().toISOString(),
    securityAudit: parsedRuling
  }
}];
